<style>
.sb-tools{color:#edf3ff}.sb-tools button,.sb-tools input,.sb-tools select{font:inherit;min-height:44px;min-width:44px;border:1px solid #526580;border-radius:6px;background:#162030;color:#edf3ff;padding:6px 8px}.sb-tools button{cursor:pointer;touch-action:manipulation}.sb-tools button:disabled{opacity:.45;cursor:not-allowed}.sb-tools button:focus-visible,.sb-tools input:focus-visible,.sb-tools select:focus-visible{outline:3px solid #fbd472;outline-offset:2px}.sb-tools fieldset{border:0;padding:0;margin:0;min-width:0}.sb-tools label{display:flex;flex-direction:column;gap:4px}.sb-tools .row{display:flex;flex-wrap:wrap;gap:6px;align-items:end;margin:8px 0}.sb-tools .row>*{width:auto;max-width:100%;padding:0}.sb-tools .pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;margin-top:4px}.sb-tools input,.sb-tools select{max-width:100%;min-width:0}.sb-tools h2{font-size:16px;color:#edf3ff;margin:6px 0}.sb-tools p{margin:8px 0}.sb-tools .start{background:#123e30}.sb-tools .danger{border-color:#d27989;color:#ffc3ce}.sb-tools .dock{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px;padding:5px;background:#0e1725;border-radius:8px}.sb-tools .dock button{flex:1 1 44px}.sb-tools dialog{background:#111b2b;color:#edf3ff;border:1px solid #d4e7ff40;border-radius:12px;width:min(94vw,540px);max-height:90dvh;overflow:auto;padding:20px;box-shadow:0 20px 70px #0008,inset 0 1px #ffffff18}.sb-tools dialog::backdrop{background:#000b}.sb-tools dialog input,.sb-tools dialog select{display:block;width:120px;margin-bottom:10px}.sb-tools dialog button{margin-top:6px}.sb-tools .focus-dialog header{display:flex;align-items:center;justify-content:space-between;position:sticky;top:-20px;background:#172238;padding:6px 0;z-index:1}.sb-tools .focus-dialog header button{margin-left:auto}.sb-tools [data-focus-error]{color:#ffbdc7}.sb-tools .period-picker{display:flex;align-items:center;justify-content:center;gap:18px}.sb-tools .period-picker output{font-size:28px;font-weight:700}.sb-too